import time
import sys
from gpiozero import PWMOutputDevice

# GPIO pins for the three LEDs
LED_PINS = [1, 2, 3]

def set_led_brightness(pwm_device, brightness):
    """Sets the brightness of each LED using PWM."""
    # Apply the brightness level to each LED pin
    for pin in LED_PINS:
        pwm_device.value = brightness
        print(f"Setting LED on pin {pin} to brightness {brightness:.2f}")

def main():
    """Controls the brightness of three LEDs connected to the Raspberry Pi."""
    # Initialize PWM output devices for each LED pin
    led_pwm_devices = []
    try:
        for pin in LED_PINS:
            led_pwm_devices.append(PWMOutputDevice(pin, frequency=1000))
        print("Starting LED brightness control...")
        # Loop to continuously adjust the brightness
        while True:
            # Prompt the user for a brightness value
            try:
                brightness = float(input("Enter LED brightness (0.0 - 1.0): "))
                # Validate the input brightness value
                if 0.0 <= brightness <= 1.0:
                    # Set the brightness for each LED
                    for pwm_device in led_pwm_devices:
                        set_led_brightness(pwm_device, brightness)
                else:
                    print("Invalid brightness value. Please enter a value between 0.0 and 1.0.")
            except ValueError:
                print("Invalid input. Please enter a numeric value.")
            # Wait for a short interval
            time.sleep(0.1)
    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully
        print("\nExiting program.")
    finally:
        # Ensure all PWM devices are released
        for pwm_device in led_pwm_devices:
            pwm_device.close()
        print("GPIO resources released.")

if __name__ == "__main__":
    main()

