import time
import board
import busio
import adafruit_mcp3xxx.mcp3xxx as MCP3XXX

# Configuration constants
ADC_READINGS_COUNT = 5
SAMPLING_INTERVAL_SECONDS = 60


def initialize_i2c():
    """Initialize the I2C bus."""
    return busio.I2C(board.SCL, board.SDA)


def initialize_adc(i2c_bus):
    """Initialize the MCP3008 ADC."""
    return MCP3XXX.MCP3XXX(i2c_bus, clip_value=False)


def read_adc_channel(adc_device, channel_number):
    """Read the analog value from the specified ADC channel."""
    return adc_device[channel_number]


def validate_adc_reading(reading_value):
    """Check if the ADC reading is valid."""
    return 0 <= reading_value <= 1023


def process_adc_reading(reading_value):
    """Print the ADC reading to standard output."""
    if validate_adc_reading(reading_value):
        print(f"ADC Channel {board.ADC_CHANNEL}: {reading_value}")
    else:
        print(f"Invalid ADC reading: {reading_value}")


def main():
    """Main function to sample and process ADC readings."""
    i2c_bus = initialize_i2c()
    adc_device = initialize_adc(i2c_bus)

    try:
        for _ in range(ADC_READINGS_COUNT):
            adc_value = read_adc_channel(adc_device, board.ADC_CHANNEL)
            process_adc_reading(adc_value)
            time.sleep(SAMPLING_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Sampling interrupted by user.")
    finally:
        # No specific cleanup needed for MCP3XXX, but including for good practice
        print("Exiting program.")


if __name__ == "__main__":
    main()

