import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration constants
ADC_ADDRESS = 0x48
SAMPLE_INTERVAL_SECONDS = 1
READ_COUNT = SAMPLE_INTERVAL_SECONDS

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initialize the ADS1115 ADC."""
    try:
        adc = ADS.ADS1115(i2c_bus, address=ADC_ADDRESS)
        return adc
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def configure_analog_channel(adc_device):
    """Configure the analog input channel."""
    try:
        channel = AnalogIn(adc_device, 0)  # Using channel 0
        return channel
    except Exception as e:
        print(f"Error configuring analog channel: {e}")
        return None

def read_adc_value(adc_device, channel):
    """Read the analog value from the specified channel."""
    try:
        return channel.value
    except Exception as e:
        print(f"Error reading ADC value: {e}")
        return None

def validate_adc_reading(reading):
    """Validate the ADC reading."""
    if reading is not None:
        return 0 <= reading <= 32767
    return False

def process_adc_reading(reading):
    """Print the ADC reading."""
    if reading is not None and validate_adc_reading(reading):
        print(f"ADC Reading: {reading}")

def main():
    """Main function to sample and print ADC readings."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    adc_device = initialize_adc(i2c_bus)
    if adc_device is None:
        return

    channel = configure_analog_channel(adc_device)
    if channel is None:
        return

    try:
        for _ in range(READ_COUNT):
            adc_value = read_adc_value(adc_device, channel)
            process_adc_reading(adc_value)
            time.sleep(SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Sampling interrupted by user.")
    finally:
        # No specific cleanup needed for adafruit-ads1x15, but including for good practice
        print("Exiting program.")

