from gpiozero import DigitalOutputDevice
import atexit

# Define the GPIO pin numbers using BCM numbering
LED_PIN = 2
BUTTON_PIN = 17

def initialize_gpio():
    """Initialize the GPIO devices and register cleanup function."""
    try:
        led = DigitalOutputDevice(LED_PIN)
        button = DigitalOutputDevice(BUTTON_PIN)
        atexit.register(led.close)  # Ensure LED is turned off on exit
        atexit.register(button.close) # Ensure Button is released on exit
        return led, button
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return None, None

def set_led_state(led, state):
    """Set the LED state based on the provided boolean value."""
    try:
        if state:
            led.on()
            print("LED is ON")
        else:
            led.off()
            print("LED is OFF")
    except Exception as e:
        print(f"Error setting LED state: {e}")

def main():
    """Main function to demonstrate LED control."""
    led, button = initialize_gpio()

    if led is None or button is None:
        return  # Exit if GPIO initialization failed

    try:
        set_led_state(led, True)  # Turn LED on
        # Add button interaction logic here if needed
        print("Press Ctrl+C to exit.")
        import signal
        signal.pause()
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        # Ensure cleanup on exit
        if led:
            led.close()
        if button:
            button.close()
        print("GPIO resources released.")

if __name__ == "__main__":
    main()

