from gpiozero import DigitalOutputDevice
import atexit

# Define the GPIO pin numbers
RELAY_PIN = 17
LIGHT_PIN = 27

def setup_relay_and_light():
    """Sets up the relay and light objects using gpiozero."""
    try:
        relay = DigitalOutputDevice(RELAY_PIN, active_high=True, initial_value=False)
        light = DigitalOutputDevice(LIGHT_PIN, active_high=True, initial_value=False)
        return relay, light
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        return None, None

def apply_relay_state(relay, light, state):
    """Applies the specified state to the relay and light."""
    try:
        if relay:
            relay.on() if state == "on" else relay.off()
        if light:
            light.on() if state == "on" else light.off()
        print(f"State applied: {state}")
    except Exception as e:
        print(f"Error applying state: {e}")

def cleanup(relay, light):
    """Releases the GPIO resources."""
    if relay:
        relay.close()
    if light:
        light.close()

def main():
    """Main function to demonstrate the relay and light control."""
    relay, light = setup_relay_and_light()

    if relay and light:
        apply_relay_state(relay, light, "on")
        atexit.register(cleanup, relay, light) # Ensure cleanup on exit
    else:
        print("GPIO setup failed. Exiting.")

if __name__ == "__main__":
    main()

