# Reads the TSL2561 light sensor over I2C and prints the measurement.

import smbus2
import time

# I2C address of the TSL2561 light sensor
TSL2561_ADDRESS = 0x39

# Initialize the I2C bus
i2c_bus = smbus2.SMBus(1)

def read_light_level():
    """Reads the raw light level from the TSL2561 sensor."""
    try:
        raw_data = i2c_bus.read_i2c_block_data(TSL2561_ADDRESS, 0x00, 2)
        light_value = (raw_data[0] << 8) | raw_data[1]
        return light_value
    except Exception as sensor_error:
        print(f"Sensor read error: {sensor_error}")
        return None

def validate_light_level(light_value):
    """Validates the light level reading."""
    if light_value is None:
        return False
    return True

def main():
    """Main function to continuously read and print light levels."""
    try:
        while True:
            light_level = read_light_level()
            if validate_light_level(light_level):
                print(f"Light Level: {light_level}")
            else:
                print("Invalid light level reading.")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        i2c_bus.close()
        print("I2C bus closed.")

if __name__ == "__main__":
    main()

