import time
from w1thermsensor import W1ThermSensor, W1ThermSensorError

def read_temperature(sensor):
    """Read and return the current temperature in Celsius."""
    try:
        return sensor.get_temperature()
    except W1ThermSensorError:
        return None

def validate_reading(temperature):
    """Return True when the temperature reading is valid."""
    return temperature is not None

def report_temperature(temperature):
    """Print the temperature reading to standard output."""
    if temperature is not None:
        print("Temperature: {:.1f} °C".format(temperature))
    else:
        print("Error: Could not read temperature.")

def main():
