import time
import sys
from gpiozero import PWMOutputDevice, CPUTemperature, DigitalInputDevice

# Define GPIO pins for LEDs and fan
LED_PINS = [12, 13, 18, 19, 22, 23]
FAN_PIN = 4

# Initialize GPIO devices
try:
    led1 = PWMOutputDevice(LED_PINS[0])
    led2 = PWMOutputDevice(LED_PINS[1])
    led3 = PWMOutputDevice(LED_PINS[2])
    led4 = PWMOutputDevice(LED_PINS[3])
    fan = PWMOutputDevice(FAN_PIN)
    cpu = CPUTemperature()
except Exception as e:
    print(f"Error initializing GPIO: {e}")
    sys.exit(1)


def get_cpu_temp():
    """Reads and returns the current CPU temperature."""
    try:
        return cpu.temperature
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None


def set_led_brightness(led, brightness):
    """Sets the brightness of a specified LED."""
    try:
        led.value = brightness
    except Exception as e:
        print(f"Error setting LED brightness: {e}")


def control_led_sequence(leds, state):
    """Turns on or off a sequence of LEDs."""
    try:
        for led in leds:
            set_led_brightness(led, state)
    except Exception as e:
        print(f"Error controlling LED sequence: {e}")


def main():
    """Main function to control LEDs and fan based on CPU temperature."""
    try:
        while True:
            cpu_temp = get_cpu_temp()
            if cpu_temp is None:
                time.sleep(2)
                continue

            temp_diff = 2.0  # Default temperature difference
            if cpu_temp > 70:
                temp_diff = 1.0
            elif 40 <= cpu_temp <= 70:
                temp_diff = 0.5
            else:
                temp_diff = 0.0

            # Control LED sequence based on CPU temperature
            led_sequence = [led3, led4, led2, led1] if cpu_temp > 40 else [led1, led2, led3, led4]
            control_led_sequence(led_sequence, temp_diff)

            # Control fan speed based on CPU temperature
            if cpu_temp > 70:
                fan.value = 1.0
            elif 40 <= cpu_temp <= 70:
                fan.value = 0.5
            else:
                fan.value = 0.0

            print(f"CPU Temp: {cpu_temp:.1f}°C")
            time.sleep(2)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure all LEDs are turned off and GPIO resources are released
        led1.off()
        led2.off()
        led3.off()
        led4.off()
        fan.off()
        print("GPIO resources released.")


if __name__ == "__main__":
    main()

import time
import Adafruit_ADS1x15
from contextlib import contextmanager

# Constants
ADC_ADDRESS = 0x48
READ_INTERVAL_SECONDS = 0.001


@contextmanager
def adc_device():
    """Context manager for ADS1115 device."""
    try:
        device = Adafruit_ADS1x15.ADS1115(ADC_ADDRESS)
        yield device
    finally:
        device.exit()
        del device


def read_adc_channel(device, channel):
    """Reads a single channel from the ADC.

    Args:
        device: The ADS1115 device object.
        channel: The channel number to read (0-3).

    Returns:
        The raw ADC value.
        Raises ValueError if the channel is invalid or an error occurs.
    """
    if not 0 <= channel <= 3:
        raise ValueError("Invalid ADC channel. Must be between 0 and 3.")

    try:
        return device.read_adc(channel, gain=1)
    except Exception as error:
        raise ValueError(f"Error reading ADC channel {channel}: {error}")


def validate_adc_value(value):
    """Validates if the provided value is within the expected range.

    Args:
        value: The value to validate.

    Raises:
        ValueError: If the value is not within the expected range (0-32767).
    """
    if not 0 <= value <= 32767:
        raise ValueError(f"ADC value {value} is out of range (0-32767)")


def main():
    """Main function to continuously read and print ADC values."""
    with adc_device() as device:
        try:
            while True:
                try:
                    value = read_adc_channel(device, 0)
                    validate_adc_value(value)
                    print(f"Channel 0: {value}")
                except ValueError as error:
                    print(f"Error: {error}")
                time.sleep(READ_INTERVAL_SECONDS)
        except KeyboardInterrupt:
            print("Exiting...")
        except Exception as error:
            print(f"An unexpected error occurred: {error}")


if __name__ == "__main__":
    main()

