import smbus2
import time

# I2C address of the MPU6050
MPU6050_ADDRESS = 0x68

# Initialize the I2C bus
i2c_bus = smbus2.SMBus(1)

def read_mpu6050_data():
    """Reads accelerometer and gyroscope data from the MPU6050."""
    try:
        # Read six bytes of data (accel X, accel Y, accel Z, gyro X, gyro Y, gyro Z)
        raw_data = i2c_bus.read_i2c_block_data(MPU6050_ADDRESS, 0x3B, 6)
        accel_x = raw_data[0] | (raw_data[1] << 8)
        if accel_x > 32767:
            accel_x -= 65536
        accel_y = raw_data[2] | (raw_data[3] << 8)
        if accel_y > 32767:
            accel_y -= 65536
        accel_z = raw_data[4] | (raw_data[5] << 8)
        if accel_z > 32767:
            accel_z -= 65536
        gyro_x = raw_data[4] | (raw_data[5] << 8)
        if gyro_x > 32767:
            gyro_x -= 65536
        gyro_y = raw_data[6] | (raw_data[7] << 8)
        if gyro_y > 32767:
            gyro_y -= 65536
        gyro_z = raw_data[6] | (raw_data[7] << 8)
        if gyro_z > 32767:
            gyro_z -= 65536
        return accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z
    except Exception as error:
        print(f"Error reading MPU6050 data: {error}")
        return None, None, None, None, None, None

def main():
    """Main function to read and print MPU6050 data."""
    try:
        # Read data five times with a short delay
        for _ in range(5):
            accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z = read_mpu6050_data()
            if accel_x is not None and accel_y is not None and accel_z is not None and gyro_x is not None and gyro_y is not None and gyro_z is not None:
                print(f"Accel X: {accel_x}, Accel Y: {accel_y}, Accel Z: {accel_z}")
                print(f"Gyro X: {gyro_x}, Gyro Y: {gyro_y}, Gyro Z: {gyro_z}")
            else:
                print("Failed to read MPU6050 data.")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        # Close the I2C bus
        i2c_bus.close()
        print("I2C bus closed.")

if __name__ == "__main__":
    main()

