class ErrorHandler:
    """Context manager for handling exceptions during resource usage."""

    def __init__(self, func, *args, **kwargs):
        """Initializes the context manager."""
        self.func = func
        self.resource = None
        self.args = args
        self.kw = kwargs

    def __enter__(self):
        """Acquires the resource."""
        try:
            self.resource = self.func(*self.args, **self.kw)
