        raw_data = i2c_bus.read_i2c_block_data(TSL2591_ADDRESS, 0x00, 3)

        # Combine the two bytes into a single 16-bit value
        full_spectrum = (raw_data[0] << 8) | raw_data[1]
        infrared = (raw_data[2] << 8) | raw_data[1]

