def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_adc(i2c_bus):
    """Initialize the MCP3008 ADC."""
    try:
        return MCP3XXX.MCP3XXX(i2c_bus, addr=0x18)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None


def read_adc_channel(adc_object, channel_number):
    """Read the analog value from the specified channel."""
    try:
        return adc_object.read_adc(channel_number, continuous_read=False)
    except Exception as e:
        print(f"Error reading ADC channel {channel_number}: {e}")
        return None


def validate_adc_reading(reading_value):
    """Validate if the ADC reading is within a reasonable range."""
    return 0 <= reading_value <= 1023


def process_adc_data(adc_object, channel_number, sample_count, interval):
    """Sample the ADC, validate, and print the data."""
    valid_readings = 0
    last_valid_reading = 0

    for _ in range(sample_count):
        reading = read_adc_channel(adc_object, channel_number)

        if reading is not None and validate_adc_reading(reading):
            last_valid_reading = reading
            print(f"Channel {channel_number}: {reading}")
            valid_readings += 1
        else:
            print(f"Channel {channel_number}: Invalid reading. Last valid reading: {last_valid_reading}")

        time.sleep(interval)


def main():
    """Main function to read and process ADC data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    adc = initialize_adc(i2c_bus)
    if adc is None:
        return

    try:
        while True:
            process_adc_data(adc, ADC_CHANNEL, MAX_READINGS, SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        # No specific cleanup needed for MCP3008 in this library, but good practice to include a 'finally' block
        print("Program finished.")


if __name__ == "__main__":
    main()

import time
import board
import adafruit_dht

# Configuration
DHT_PIN = board.D4
SAMPLE_INTERVAL = 5  # seconds
NUM_SAMPLES = 3

# Initialize DHT22 sensor
dht_device = adafruit_dht.DHT22(DHT_PIN)

def read_temperature():
    """Reads temperature from DHT22 sensor and returns the value."""
    try:
        temperature_c = dht_device.temperature
        if temperature_c is not None:
            return temperature_c
        else:
            return None
    except RuntimeError as error:
        # Errors happen fairly often, DHT's are hard to read, just keep going
        print(f"DHT Sensor RuntimeError: {error}")
        return None
    except Exception as error:
        print(f"DHT Sensor Error: {error}")
        return None

def report_reading(temperature):
    """Prints the temperature reading to the console."""
    if temperature is not None:
        print(f"Temperature: {temperature:.1f} C")
    else:
        print("Failed to read temperature.")

def main():
    """Main function to read and report temperature data."""
    try:
        for i in range(NUM_SAMPLES):
            temperature = read_temperature()
            report_reading(temperature)
            time.sleep(SAMPLE_INTERVAL)
        print("Temperature monitoring completed.")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # No specific cleanup needed for DHT22 in this library, but good practice to include
        print("Exiting program.")

if __name__ == "__main__":
    main()
